                    @Override
                    public void onSuccess(List<RatingDto> ratings) {
                        getView().displayRatings(ratings);
                    }
                })
                .getRatings();
    }
    @Override
    protected void onBind() {
        addRegisteredHandler(ActionBarEvent.getType(), this);
    }
}
