// Minimal Chromium DevTools driver used to replay the Cucumber scenarios (no Selenium available here).
const WebSocket = require('/work/node_modules/ws');
const { spawn } = require('child_process');
const http = require('http');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function getJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

async function launch(port) {
  const proc = spawn('/usr/bin/chromium', [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    '--window-size=1280,900', `--remote-debugging-port=${port}`,
    `--user-data-dir=/tmp/e2e-harness/profile-${process.pid}`, 'about:blank',
  ], { stdio: 'ignore' });
  let targets;
  for (let i = 0; i < 100; i++) {
    try { targets = await getJson(`http://127.0.0.1:${port}/json/list`); break; } catch (e) { await sleep(100); }
  }
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise((res, rej) => { ws.on('open', res); ws.on('error', rej); });
  let id = 0;
  const pending = new Map();
  ws.on('message', (raw) => {
    const msg = JSON.parse(raw);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
    }
  });
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const mid = ++id;
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Page.setLifecycleEventsEnabled', { enabled: true });
  return { proc, ws, send, close: () => { try { ws.close(); } catch (e) {} proc.kill('SIGKILL'); } };
}

class Browser {
  constructor(cdp) { this.cdp = cdp; this.log = []; }

  async evaluate(expr) {
    const r = await this.cdp.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (r.exceptionDetails) throw new Error('JS error: ' + (r.exceptionDetails.exception?.description || r.exceptionDetails.text));
    return r.result.value;
  }

  async navigate(url) {
    await this.cdp.send('Page.navigate', { url });
    await this.waitFor(`document.readyState === 'complete' && !!document.querySelector('app-root *')`, 20000, `load ${url}`);
  }

  async waitFor(expr, timeout = 10000, what = expr) {
    const start = Date.now();
    let last;
    while (Date.now() - start < timeout) {
      try { last = await this.evaluate(`(() => { try { return !!(${expr}); } catch (e) { return false; } })()`); } catch (e) { last = false; }
      if (last) return true;
      await sleep(100);
    }
    throw new Error(`Timed out after ${timeout}ms waiting for: ${what}`);
  }

  // Selenium-like "displayed" check.
  isDisplayedExpr(sel) {
    return `(() => { const el = document.querySelector(${JSON.stringify(sel)}); if (!el) return false;
      const r = el.getBoundingClientRect(); const cs = getComputedStyle(el);
      let node = el; while (node) { const s = getComputedStyle(node); if (s.display === 'none' || s.visibility === 'hidden' || parseFloat(s.opacity) === 0) return false; node = node.parentElement; }
      return r.width > 0 && r.height > 0; })()`;
  }

  async waitVisible(sel, timeout = 10000) { return this.waitFor(this.isDisplayedExpr(sel), timeout, `visible ${sel}`); }
  async waitClickable(sel, timeout = 10000) {
    return this.waitFor(`(() => { const el = document.querySelector(${JSON.stringify(sel)}); return !!el && !el.disabled && (${this.isDisplayedExpr(sel)}); })()`, timeout, `clickable ${sel}`);
  }
  async waitGone(sel, timeout = 10000) { return this.waitFor(`!document.querySelector(${JSON.stringify(sel)})`, timeout, `gone ${sel}`); }

  async click(sel) {
    const pt = await this.evaluate(`(() => { const el = document.querySelector(${JSON.stringify(sel)});
      if (!el) return null; el.scrollIntoView({block: 'center'}); const r = el.getBoundingClientRect();
      const x = r.left + r.width / 2, y = r.top + r.height / 2; const hit = document.elementFromPoint(x, y);
      return { x, y, intercepted: !(hit === el || el.contains(hit)), hit: hit ? hit.outerHTML.slice(0, 120) : null }; })()`);
    if (!pt) throw new Error(`click: no element ${sel}`);
    if (pt.intercepted) throw new Error(`click: ${sel} is obscured by ${pt.hit}`);
    await this.cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x, y: pt.y });
    await this.cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await this.cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x, y: pt.y, button: 'left', clickCount: 1 });
    await sleep(50);
  }

  // Selenium clear() + sendKeys()
  async type(sel, text) {
    await this.click(sel);
    await this.cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65 });
    await this.cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'a', code: 'KeyA', modifiers: 2, windowsVirtualKeyCode: 65 });
    await this.cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Backspace', code: 'Backspace', windowsVirtualKeyCode: 8 });
    await this.cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Backspace', code: 'Backspace', windowsVirtualKeyCode: 8 });
    await this.cdp.send('Input.insertText', { text });
    await sleep(50);
  }

  async overrideConfirm(value) {
    await this.evaluate(`window.confirm = function(msg){ return ${value}; };`);
  }

  async text(expr) { return this.evaluate(expr); }
  async screenshot(path) {
    const r = await this.cdp.send('Page.captureScreenshot', { format: 'png' });
    require('fs').writeFileSync(path, Buffer.from(r.data, 'base64'));
  }
}

module.exports = { launch, Browser, sleep };
