// Replays the e2e/ Cucumber scenarios (Manufacturers, Ratings, Reports) against http://localhost:8888/ng/.
const assert = require('assert');
const { launch, Browser, sleep } = require('./cdp');

const BASE = process.env.BASE || 'http://localhost:8888/ng/';
const T = {
  manufacturers: '#gwt-debug-manufacturers',
  ratings: '#gwt-debug-ratings',
  reports: '#gwt-debug-reports',
  menubar: '#gwt-debug-menubar',
};

const results = [];
async function scenario(name, fn) {
  try { await fn(); results.push([true, name]); console.log('PASS', name); }
  catch (e) { results.push([false, name, e.message]); console.log('FAIL', name, '\n   ', e.message); }
}

// ---- PageWithEditTable helpers ----
async function numberOfLines(b, table) {
  return b.evaluate(`document.querySelectorAll('${table} > tbody:first-of-type > tr').length`);
}
async function cellText(b, table, colName, row) {
  return b.evaluate(`(() => {
    const ths = [...document.querySelectorAll('${table} thead th')];
    const idx = ths.findIndex(th => th.textContent.trim() === ${JSON.stringify(colName)});
    if (idx < 0) throw new Error('no column ${colName}');
    const td = document.querySelector('${table} > tbody:first-of-type > tr:nth-child(${row}) > td:nth-child(${'${idx+1}'})');
    return td ? td.textContent.trim() : null;
  })()`);
}
async function deleteFirstRow(b, table) {
  const btn = `${table} tbody td:last-child button`;
  await b.waitClickable(btn);
  await b.overrideConfirm('true');
  await b.evaluate(`window.__stale = document.querySelector(${JSON.stringify(btn)})`);
  await b.click(btn);
  await b.waitFor(`!window.__stale.isConnected`, 10000, 'delete button detached');
}
async function editFirstRow(b, table) {
  const btn = `${table} tbody td:nth-last-child(2) button`;
  await b.waitClickable(btn);
  await b.click(btn);
}

// ---- MessageWidgetPage helpers ----
// hasSuccessMessage(msg): immediate lookup (no wait), like the Java page object.
async function hasSuccessMessage(b, msg) {
  for (;;) {
    const info = await b.evaluate(`(() => { const c = document.getElementById('gwt-debug-successMessage');
      if (!c) return null; const first = c.querySelector('span'); return { text: first ? first.textContent : '' }; })()`);
    if (info === null) throw new Error('no #gwt-debug-successMessage element');
    if (info.text && info.text.includes(msg)) {
      await b.waitVisible('#gwt-debug-successMessage');
      return true;
    }
    await b.click('#gwt-debug-successMessage > span:last-child');
    await b.waitFor(`!window.__c || !window.__c.isConnected`, 1000).catch(() => {});
    await sleep(50);
  }
}

async function navigateTo(b, token) {
  await b.click(`${T.menubar} a[href*="${token}"]`);
  await b.waitFor(`location.href.includes('#${token}')`, 10000, `url #${token}`);
}

async function main() {
  const cdp = await launch(9333);
  const b = new Browser(cdp);
  const ok = async (fn) => fn();
  try {
    // Background: I'm logged in (no login in this app), I navigate to the manufacturer page
    const freshPage = async (hash) => { await b.navigate(BASE + hash); await b.waitVisible(T.menubar); };

    // ===== Manufacturers.feature =====
    await scenario('Manufacturers: create shows the editor', async () => {
      await freshPage('#manufacturer');
      await b.waitVisible(T.manufacturers);
      await b.click('#gwt-debug-create-manufacturer');
      await b.waitVisible('#gwt-debug-manufacturer-editor');
    });

    await scenario('Manufacturers: close leaves table unchanged', async () => {
      await freshPage('#manufacturer');
      await b.waitVisible(T.manufacturers);
      const before = await numberOfLines(b, T.manufacturers);
      await b.click('#gwt-debug-create-manufacturer');
      await b.waitVisible('#gwt-debug-manufacturer-editor');
      await b.type('#gwt-debug-manufacturer-input', 'Ford');
      await b.click('#gwt-debug-manufacturer-close');
      await b.waitGone('#gwt-debug-manufacturer-editor');
      assert.strictEqual(await numberOfLines(b, T.manufacturers), before);
    });

    await scenario('Manufacturers: save new one -> success + row added at end', async () => {
      await freshPage('#manufacturer');
      await b.waitVisible(T.manufacturers);
      const before = await numberOfLines(b, T.manufacturers);
