    const idx = ths.findIndex(th => th.textContent.trim() === ${JSON.stringify(colName)});
    if (idx < 0) throw new Error('no column ${colName}');
    const td = document.querySelector('${table} > tbody:first-of-type > tr:nth-child(${row}) > td:nth-child(${'${idx+1}'})');
    return td ? td.textContent.trim() : null;
  })()`);
}
async function deleteFirstRow(b, table) {
  const btn = `${table} tbody td:last-child button`;
  await b.waitClickable(btn);
  await b.overrideConfirm('true');
  await b.evaluate(`window.__stale = document.querySelector(${JSON.stringify(btn)})`);
  await b.click(btn);
  await b.waitFor(`!window.__stale.isConnected`, 10000, 'delete button detached');
}
