const { launch, Browser, sleep } = require('./cdp');
(async () => {
  const cdp = await launch(9337); const b = new Browser(cdp);
  const events = [];
  cdp.ws.on('message', (raw) => { const m = JSON.parse(raw);
    if (m.method === 'Network.requestWillBeSent') events.push('REQ ' + m.params.request.url);
    if (m.method === 'Network.responseReceived') events.push('RESP ' + m.params.response.status + ' ' + m.params.response.url);
    if (m.method === 'Network.loadingFailed') events.push('FAIL ' + JSON.stringify(m.params).slice(0,200));
    if (m.method === 'Runtime.consoleAPICalled') events.push('CONSOLE ' + m.params.type + ' ' + JSON.stringify(m.params.args.map(a => a.value || a.description)).slice(0,300));
    if (m.method === 'Runtime.exceptionThrown') events.push('EXC ' + JSON.stringify(m.params.exceptionDetails).slice(0,400));
  });
  try {
    await cdp.send('Network.enable');
    await b.cdp.send('Page.navigate', { url: 'about:blank' }); await sleep(200);
    await b.navigate('http://localhost:8888/ng/#manufacturer');
    await b.waitVisible('#gwt-debug-manufacturers');
    await sleep(1500);
    console.log(events.join('\n'));
  } finally { cdp.close(); }
})();
EOF
