package com.gwtplatform.carstore.cucumber;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import cucumber.api.guice.CucumberModules;
import cucumber.runtime.java.guice.InjectorSource;

/**
 * Tells cucumber-guice how to build the injector: scenario scope plus one shared browser.
 *
 * The browser is ChromeDriver. Set CHROMEDRIVER to the chromedriver binary (or put it on the PATH)
 * and CHROME_BIN to the Chrome/Chromium binary if it is not the default one.
 */
public class CarStoreInjectorSource implements InjectorSource {
    @Override
    public Injector getInjector() {
        return Guice.createInjector(CucumberModules.SCENARIO, new AbstractModule() {
            @Override
            protected void configure() {
                bind(WebDriver.class).toInstance(SharedBrowser.get());
            }
        });
    }

    /** One headless browser for the whole run, closed when the JVM exits. */
    private static final class SharedBrowser {
        private static WebDriver driver;

        private SharedBrowser() {
        }

        static synchronized WebDriver get() {
            if (driver == null) {
                String chromedriver = System.getenv("CHROMEDRIVER");
                if (System.getProperty("webdriver.chrome.driver") == null && chromedriver != null) {
                    System.setProperty("webdriver.chrome.driver", chromedriver);
                }

                ChromeOptions options = new ChromeOptions();
                options.addArguments("--headless", "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
                        "--window-size=1280,900");
                String chromeBinary = System.getenv("CHROME_BIN");
                if (chromeBinary != null) {
                    options.setBinary(chromeBinary);
                }

                final WebDriver created = new ChromeDriver(options);
                Runtime.getRuntime().addShutdownHook(new Thread(created::quit));
                driver = created;
            }
            return driver;
        }
    }
}

