package com.gwtplatform.carstore.cucumber.stepdefs;

import com.gwtplatform.carstore.cucumber.util.TestParameters;

import cucumber.api.java.en.Given;
import cucumber.api.java.en.Then;
import cucumber.runtime.java.guice.ScenarioScoped;

import static org.junit.Assert.assertTrue;

/** Steps shared by the Manufacturers, Ratings and Reports features. */
@ScenarioScoped
public class GeneralStepDefs extends StepDefs {
    @Given("^I'm logged in$")
    public void iAmLoggedIn() {
        // The app has no login (login is out of scope and the REST API is not protected),
        // so "logged in" means the application is open and its shell is rendered.
        headerWidgetPage.getUrl(TestParameters.APP_URL);
    }

    @Given("^I navigate to the (manufacturer|rating|report) page$")
    public void iNavigateToThePage(String nameToken) {
        headerWidgetPage.navigateTo(nameToken);
        headerWidgetPage.waitUntilPlaceIsLoaded(nameToken);
    }

    @Then("^I see a success message containing (.+)$")
    public void iSeeASuccessMessageContaining(String message) {
        assertTrue(messageWidgetPage.hasSuccessMessage(message));
    }
}

